head.script:
(function () {
  const ns = "http://www.w3.org/1999/xhtml";
  const d = document;
  const root = d.getElementsByTagName("foreignObject")[0].firstElementChild;
  const createElement = d.createElement.bind(d);
  const createElementNS = d.createElementNS.bind(d);
  Object.defineProperties(d, {
    head: { configurable: true, get: () => root.querySelector("head") },
    body: { configurable: true, get: () => root.querySelector("body") },
    documentElement: { configurable: true, get: () => root }
  });
  d.createElement = function (name, options) {
    return typeof name === "string" ? createElementNS(ns, name, options) : createElement(name, options);
  };
  d.createElementNS = function (namespace, name, options) {
    return createElementNS(namespace == null ? ns : namespace, name, options);
  };
})();

import("https://cdn.jsdelivr.net/gh/nicholasgameproductions-rgb/svg@main/assets/index-DQjm01-w-4be15021.js").catch(function (err) {
  const root = document.getElementById("root");
  if (root) root.textContent = "NicholasGPProxy could not load its JavaScript. Check that the assets/ folder is uploaded to GitHub. " + err.message;
  console.error(err);
});
